'use strict';
// Scripted authenticated review. No OAuth, mailbox scan or network save occurs.
const gmailReview={email:'alex@example.com',stage:0,started:false,timer:null,token:0,selected:new Set(['new-notion-team','new-figma-trial']),imported:new Set(),saving:false,dateOverride:false,origin:'List',intent:'sync'};
const gmailCandidates=[
 {id:'new-notion-team',kind:'new',record:{id:'gmail-notion-team',platformId:'notion',providerSubscriptionId:'notion-team-42',name:'Notion',plan:'Team plan',price:'12.00',currency:'USD',cycle:'Monthly',category:'Productivity',start:'2026-10-25',renewal:'2026-11-25',source:'Gmail',inboxEmail:'alex@example.com'}},
 {id:'new-figma-trial',kind:'new',record:{id:'gmail-figma-trial',platformId:'figma',providerSubscriptionId:'figma-pro-trial-73',name:'Figma',plan:'Professional trial',price:'15.00',currency:'USD',cycle:'Monthly',category:'Productivity',start:'2026-10-24',trialDays:14,trialEnd:'2026-11-07',trialEndSource:'exact',trialDuration:'14 days',autoRenew:true,renewal:'2026-11-07',source:'Gmail',inboxEmail:'alex@example.com'}},
 {id:'update-netflix',kind:'update',targetId:'netflix-primary',name:'Netflix',currency:'USD',cycle:'Monthly',changes:{price:'17.99',renewal:'2026-11-27'},old:{price:'15.99',renewal:'2026-10-27'},preserveManualDate:true},
 {id:'tracked-spotify',kind:'duplicate',targetId:'spotify',name:'Spotify',price:'11.99',currency:'USD'}
];
function gmailSelectedCandidates(){return gmailCandidates.filter(c=>c.kind!=='duplicate'&&!gmailReview.imported.has(c.id)&&gmailReview.selected.has(c.id));}
function gmailApplyCandidate(candidate,existing,email,overrideDate=false,connectorId=''){if(candidate.kind==='duplicate')return null;if(candidate.kind==='new')return {...candidate.record,source:'Gmail',inboxEmail:email,connectorId};if(!existing||existing.id!==candidate.targetId)return null;const result={...existing,supplementalInboxEmail:email};if(candidate.changes.price!==undefined)result.price=candidate.changes.price;if(candidate.changes.renewal&&(!candidate.preserveManualDate||overrideDate)){result.renewal=candidate.changes.renewal;result.estimated=false;}return result;}
function gmailPeriodMoney(items){const totals={};for(const c of items.filter(c=>c.kind==='new')){const r=c.record,factor=({Weekly:52/12,Monthly:1,Quarterly:1/3,Yearly:1/12})[r.cycle]||1;totals[r.currency]=(totals[r.currency]||0)+Number(r.price)*factor;}return Object.entries(totals).map(([currency,value])=>currency+' '+value.toFixed(2)).join(' · ');}
function gmailReviewHeader(title='Gmail review'){return `<div class="head gmail-review-header">${backButton({attributes:`data-gmail-action="back"`,label:"Go back",className:""})}<h2>${title}</h2><span class="gmail-header-logo">${platformLogo('Gmail')}</span></div>`;}
function gmailInboxRow(){return `<button class="gmail-inbox-switch" data-gmail-action="inboxes"><span>${platformLogo('Gmail')}<span>${escape(gmailReview.email)}</span></span><span>Change <i aria-hidden="true">⌄</i></span></button>`;}
function gmailFooter(label,action,disabled=false,copy=''){return `<footer class="gmail-review-footer"><button class="primary" data-gmail-action="${action}" ${disabled?'disabled':''}>${label}</button>${copy?`<p>${copy}</p>`:''}</footer>`;}
function gmailScanScreen(){const labels=['Finding subscription receipts','Matching your subscriptions','Checking renewals & trials'];return `<div class="gmail-layout">${gmailReviewHeader('Find subscriptions')}${gmailInboxRow()}<div class="gmail-scan-visual ${gmailReview.stage===3?'complete':''}">${mascotView({expression:gmailReview.stage===3?'happy':'scanning',size:132,artworkScale:gmailReview.stage===3?1.05:.78})}<span class="gmail-scan-ring" aria-hidden="true"></span></div><p class="eyebrow">YOUR INBOX, ORGANIZED</p><h3 class="gmail-main-title">Finding what’s new.</h3><p class="gmail-description">We’re checking receipts for subscriptions and changes to the ones you track.</p><ol class="gmail-scan-checklist" aria-live="polite">${labels.map((label,i)=>`<li aria-label="${label}: ${gmailReview.stage>i?'complete':gmailReview.stage===i?'in progress':'waiting'}" class="${gmailReview.stage>i?'done':gmailReview.stage===i?'running':''}"><span aria-hidden="true">${gmailReview.stage>i?'✓':gmailReview.stage===i?'<i class="gmail-small-spinner"></i>':'·'}</span>${label}</li>`).join('')}</ol>${gmailReview.stage===3?'<p class="gmail-scan-complete" role="status">Your results are ready to review.</p>':''}${gmailFooter('Review subscriptions','review',gmailReview.stage<3,'Only your chosen subscriptions will be saved.')}</div>`;}
function gmailCandidateRow(c){const r=c.record||c,imported=gmailReview.imported.has(c.id),trial=!!r.trialDays;return `<div class="gmail-candidate-row"><input type="checkbox" data-gmail-select="${c.id}" aria-label="Select ${escape(r.name)} ${c.kind==='update'?'update':r.plan||'subscription'}" ${gmailReview.selected.has(c.id)&&!imported?'checked':''} ${imported?'disabled':''}><span class="avatar">${platformLogo(r.name)}</span><div class="gmail-candidate-copy"><strong>${escape(r.name)}</strong><small>${c.kind==='update'?'Price change found':escape(r.plan||r.cycle)}</small>${c.kind==='update'?`<span class="gmail-change-price">${escape(c.currency)} <s>${Number(c.old.price).toFixed(2)}</s> → ${Number(c.changes.price).toFixed(2)}</span><small>${c.preserveManualDate&&!gmailReview.dateOverride?'Your saved renewal date is kept.':'Renewal · '+detailDate(c.changes.renewal)}</small>`:`<span class="${trial?'status-trial':''}">${trial?'Trial ends':'Renews'} ${detailDate(r.trialEnd||r.renewal)}</span>`}${imported?'<small class="status-active">Saved</small>':''}</div><div class="gmail-candidate-end">${c.kind!=='update'?`<strong>${escape(r.currency)} ${Number(r.price).toFixed(2)}</strong><small>${trial?'After trial · ':''}${escape(r.cycle)}</small>`:''}<button data-gmail-review-candidate="${c.id}" aria-label="Review ${escape(r.name)} ${c.kind==='update'?'changes':'details'}">${c.kind==='update'?'Review changes':'Review'} ›</button></div></div>`;}
function gmailSaveLabel(){const selected=gmailSelectedCandidates(),add=selected.filter(c=>c.kind==='new').length,updates=selected.filter(c=>c.kind==='update').length;if(gmailReview.saving)return 'Saving…';return add&&updates?'Add '+add+' & save '+updates+' update'+(updates===1?'':'s'):add?'Add '+add+' subscription'+(add===1?'':'s'):updates?'Save '+updates+' update'+(updates===1?'':'s'):'Select subscriptions';}
function gmailReviewScreen(){const selected=gmailSelectedCandidates(),newItems=gmailCandidates.filter(c=>c.kind==='new'),updates=gmailCandidates.filter(c=>c.kind==='update'),duplicates=gmailCandidates.filter(c=>c.kind==='duplicate');return `<div class="gmail-layout">${gmailReviewHeader('Review subscriptions')}${gmailInboxRow()}<p class="eyebrow">${gmailReview.intent==='first'?'SUBSCRIPTIONS FOUND':'NEW SUBSCRIPTIONS & UPDATES'}</p><h3 class="gmail-main-title">A clearer picture.</h3><p class="gmail-description">Choose what to add and which changes to keep.</p><section class="gmail-review-summary"><div><span>Selected</span><strong data-gmail-selection-count>${selected.length}</strong></div><div><span>New plans · monthly equivalent</span><strong data-gmail-selection-money>${gmailPeriodMoney(selected)||'—'}</strong><small>Trial prices apply after the trial.</small></div></section><div class="gmail-result-section"><h3>New subscriptions <span>${newItems.length}</span></h3><div class="gmail-candidate-list">${newItems.map(gmailCandidateRow).join('')}</div></div><div class="gmail-result-section"><h3>Updates found <span>${updates.length}</span></h3><div class="gmail-candidate-list">${updates.map(gmailCandidateRow).join('')}</div></div><details class="gmail-duplicates"><summary>${duplicates.length} already tracked</summary>${duplicates.map(c=>`<div><span class="avatar">${platformLogo(c.name)}</span><span><strong>${escape(c.name)}</strong><small>Already tracked · won’t be added again</small></span><span aria-hidden="true">✓</span></div>`).join('')}</details><p class="gmail-receipt-note">Matching payment receipts update your payment history automatically.</p>${gmailFooter(gmailSaveLabel(),'save',!selected.length||gmailReview.saving,'Your existing subscriptions stay available.')}</div>`;}
function gmailRecoveryScreen(interrupted){return `<div class="gmail-layout">${gmailReviewHeader(interrupted?'Scan interrupted':'Scan complete')}${gmailInboxRow()}<div class="gmail-recovery-visual">${mascotView({expression:interrupted?'sad':'neutral',size:140})}</div><p class="eyebrow">${interrupted?'LET’S TRY AGAIN':'YOU’RE UP TO DATE'}</p><h3 class="gmail-main-title">${interrupted?'Your scan was interrupted.':'No new subscriptions found.'}</h3><p class="gmail-description">${interrupted?'We couldn’t finish checking this inbox. Try again when your connection is ready.':'We didn’t find any new subscriptions or changes in this inbox.'}</p><p class="gmail-safety-note">Your saved subscriptions haven’t changed.</p><button class="gmail-recovery-secondary" data-gmail-action="${interrupted?'inboxes':'manual'}">${interrupted?'Choose another inbox':'Add manually'} ›</button>${gmailFooter(interrupted?'Try again':'Try another inbox',interrupted?'retry':'inboxes',false,'')}</div>`;}
function authenticatedGmailScreen(){return current==='Gmail · scanning'?gmailScanScreen():current==='Gmail · nothing found'?gmailRecoveryScreen(false):current==='Gmail · interrupted'?gmailRecoveryScreen(true):gmailReviewScreen();}
function refreshGmailSelection(){const selected=gmailSelectedCandidates();document.querySelector('[data-gmail-selection-count]').textContent=selected.length;document.querySelector('[data-gmail-selection-money]').textContent=gmailPeriodMoney(selected)||'—';const button=document.querySelector('[data-gmail-action=save]');button.textContent=gmailSaveLabel();button.disabled=!selected.length||gmailReview.saving;}
function beginAuthenticatedGmailScan(){clearTimeout(gmailReview.timer);gmailReview.stage=0;gmailReview.started=false;gmailReview.saving=false;gmailReview.token++;}
function gmailAfterRender(){if(current==='Gmail · scanning'&&!gmailReview.started){gmailReview.started=true;const token=gmailReview.token;const tick=()=>{if(current!=='Gmail · scanning'||token!==gmailReview.token)return;gmailReview.stage++;render();if(gmailReview.stage<3)gmailReview.timer=setTimeout(tick,1000);};gmailReview.timer=setTimeout(tick,1000);}if(current==='Trial review'&&!document.querySelector('.gmail-review-overlay'))openGmailCandidate(null,'new-figma-trial');}
let gmailDialogTrigger=null;
function closeGmailDialog(){const overlay=document.querySelector('.gmail-review-overlay');if(!overlay)return;closeSelectMenu(false);const phone=overlay.closest('.phone');overlay.remove();phone.querySelectorAll('[data-gmail-dialog-inert]').forEach(el=>{el.inert=false;el.removeAttribute('data-gmail-dialog-inert');});gmailDialogTrigger?.focus();if(current==='Trial review')go('Gmail · review');}
function gmailDialog(trigger,title,body){gmailDialogTrigger=trigger;const phone=trigger?.closest('.phone')||document.getElementById('upgraded'),overlay=document.createElement('div');overlay.className='gmail-review-overlay';overlay.innerHTML=`<div class="gmail-dialog-shade" data-close-gmail-dialog></div><section class="gmail-detail-sheet" role="dialog" aria-modal="true" aria-labelledby="gmail-dialog-title"><div class="handle"></div><header><h3 id="gmail-dialog-title">${escape(title)}</h3><button data-close-gmail-dialog aria-label="Close review">×</button></header>${body}</section>`;for(const el of phone.children){if(!el.inert){el.inert=true;el.dataset.gmailDialogInert='true';}}phone.append(overlay);syncSelectControls();overlay.querySelector('button[data-close-gmail-dialog]').focus();}
function openGmailCandidate(trigger,id){const c=gmailCandidates.find(c=>c.id===id);if(!c||c.kind==='duplicate')return;if(c.kind==='update'){gmailDialog(trigger,'Review '+c.name+' changes',`<div class="gmail-change-review">${fr('Monthly price',escape(c.currency)+' '+c.old.price+' → '+c.changes.price)}${fr('Saved renewal',detailDate(c.old.renewal))}${fr('Found in receipt',detailDate(c.changes.renewal))}<label class="gmail-replace-date"><input type="checkbox" data-gmail-date-override ${gmailReview.dateOverride?'checked':''}><span>Replace my saved renewal date<small>Keep your saved date unless you choose to replace it.</small></span></label><p>Price updates apply when you save selected results.</p><button class="primary" data-gmail-change-done>Keep these choices</button></div>`);return;}const r=c.record;gmailDialog(trigger,r.trialDays?'Review '+r.name+' trial':'Review '+r.name,`<form data-gmail-candidate-form="${c.id}" novalidate><div class="gmail-candidate-identity"><span class="avatar">${platformLogo(r.name)}</span><span>${escape(r.plan||r.name)}</span></div><label>${r.trialDays?'Price after trial':'Amount'} · ${escape(r.currency)}<input name="price" type="number" min="0.01" step="0.01" value="${r.price}" required><span class="manual-error" data-gmail-error="price" hidden></span></label>${r.trialDays?`<label>Trial start date<input name="start" type="date" value="${r.start}" required><span class="manual-error" data-gmail-error="start" hidden></span></label>${selectField({label:'Trial duration',name:'trialDays',value:String(r.trialDays),options:[...new Set([7,14,30,r.trialDays])].sort((a,b)=>a-b).map(n=>({value:String(n),label:n+' days'}))})}<p class="gmail-trial-end" aria-live="polite">Trial ends <strong>${detailDate(r.trialEnd)}</strong></p><label class="gmail-replace-date"><input name="autoRenew" type="checkbox" ${r.autoRenew?'checked':''}><span>Track renewals after trial</span></label><p class="gmail-trial-copy">${escape(r.cycle)} after trial. This doesn’t change your service settings.</p>`:`<label>Next renewal<input name="renewal" type="date" value="${r.renewal}" required><span class="manual-error" data-gmail-error="renewal" hidden></span></label>`}<button class="primary" type="submit">Keep these details</button><p class="gmail-dialog-note">Nothing is added until you save selected subscriptions.</p></form>`);}
function openGmailInboxes(trigger){gmailDialog(trigger,'Choose an inbox',`<div class="gmail-inbox-options">${profileInboxes.length?profileInboxes.map(inbox=>`<button data-gmail-inbox="${escape(inbox.email)}"><span>${platformLogo('Gmail')}</span><strong>${escape(inbox.email)}</strong>${inbox.email===gmailReview.email?'<span aria-label="Selected">✓</span>':''}</button>`).join(''):'<p>No Gmail inbox connected.</p>'}<button class="secondary" data-gmail-connect>Connect another Gmail inbox</button><p>Gmail access is separate from signing in. Connect your inboxes and keep subscriptions up to date at no cost.</p></div>`);}
function gmailCandidateErrors(values,isTrial){const errors={};if(!Number.isFinite(Number(values.price))||Number(values.price)<=0)errors.price='Enter an amount greater than zero.';for(const key of [isTrial?'start':'renewal']){const date=values[key],parsed=Date.parse(date+'T00:00:00Z');if(!/^\d{4}-\d{2}-\d{2}$/.test(date||'')||!Number.isFinite(parsed)||new Date(parsed).toISOString().slice(0,10)!==date)errors[key]='Choose a valid date.';}return errors;}
document.addEventListener('change',e=>{if(e.target.matches('[data-gmail-select]')){if(e.target.checked)gmailReview.selected.add(e.target.dataset.gmailSelect);else gmailReview.selected.delete(e.target.dataset.gmailSelect);refreshGmailSelection();}const form=e.target.closest('[data-gmail-candidate-form]');if(form&&form.elements.trialDays&&['start','trialDays'].includes(e.target.name)){const end=plusDays(form.elements.start.value,Number(form.elements.trialDays.value));form.querySelector('.gmail-trial-end strong').textContent=end?detailDate(end):'Choose a start date';}});
document.addEventListener('submit',e=>{const form=e.target.closest('[data-gmail-candidate-form]');if(!form)return;e.preventDefault();const c=gmailCandidates.find(c=>c.id===form.dataset.gmailCandidateForm),r=c.record,values={price:form.elements.price.value,start:form.elements.start?.value,renewal:form.elements.renewal?.value},errors=gmailCandidateErrors(values,!!r.trialDays);form.querySelectorAll('[data-gmail-error]').forEach(el=>{el.textContent=errors[el.dataset.gmailError]||'';el.hidden=!el.textContent;});for(const key of ['price',r.trialDays?'start':'renewal'])form.elements[key].setAttribute('aria-invalid',String(!!errors[key]));if(Object.keys(errors).length){form.elements[Object.keys(errors)[0]].focus();return;}r.price=Number(values.price).toFixed(2);if(r.trialDays){const duration=Number(form.elements.trialDays.value),changed=r.start!==values.start||r.trialDays!==duration;r.start=values.start;r.trialDays=duration;r.trialDuration=duration+' days';if(changed){r.trialEnd=plusDays(r.start,duration);r.trialEndSource='calculated';}r.renewal=r.trialEnd;r.autoRenew=form.elements.autoRenew.checked;}else r.renewal=values.renewal;closeGmailDialog();render();document.querySelector('[data-gmail-review-candidate="'+c.id+'"]')?.focus();});
document.addEventListener('click',e=>{const candidate=e.target.closest('[data-gmail-review-candidate]'),close=e.target.closest('[data-close-gmail-dialog]'),inbox=e.target.closest('[data-gmail-inbox]'),change=e.target.closest('[data-gmail-change-done]');if(candidate){openGmailCandidate(candidate,candidate.dataset.gmailReviewCandidate);return;}if(close){closeGmailDialog();return;}if(change){gmailReview.selected.add('update-netflix');gmailReview.dateOverride=change.closest('.gmail-detail-sheet').querySelector('[data-gmail-date-override]').checked;closeGmailDialog();render();document.querySelector('[data-gmail-review-candidate="update-netflix"]')?.focus();return;}if(inbox){gmailReview.email=inbox.dataset.gmailInbox;closeGmailDialog();beginAuthenticatedGmailScan();go('Gmail · scanning');return;}if(e.target.closest('[data-gmail-connect]')){toast('Gmail connection is unavailable right now. Your saved subscriptions are unchanged.');return;}const button=e.target.closest('[data-gmail-action]');if(!button)return;switch(button.dataset.gmailAction){case 'back':go(gmailReview.origin);break;case 'review':if(gmailReview.stage===3)go('Gmail · review');break;case 'inboxes':openGmailInboxes(button);break;case 'manual':go('Add form');break;case 'retry':beginAuthenticatedGmailScan();go('Gmail · scanning');break;case 'save':{const selected=gmailSelectedCandidates().map(c=>structuredClone(c)),token=gmailReview.token;if(!selected.length||gmailReview.saving)return;gmailReview.saving=true;refreshGmailSelection();document.querySelectorAll('[data-gmail-select],[data-gmail-review-candidate]').forEach(el=>el.disabled=true);setTimeout(()=>{if(token!==gmailReview.token)return;const records=gmailPrepareImport(selected,allTrackedRecords(),gmailReview.email,gmailReview.dateOverride,profileInboxes.find(i=>i.email===gmailReview.email)?.id||'');if(!records){gmailReview.saving=false;if(current==='Gmail · review')render();toast('A subscription is no longer available. Review your results and try again.');return;}records.forEach((record,i)=>{trialRecords.set(record.id,record);gmailReview.imported.add(selected[i].id);gmailReview.selected.delete(selected[i].id);});gmailReview.saving=false;if(current==='Gmail · review'){go('List');toast('Selected subscriptions and updates saved.');}},500);break;}}});
document.addEventListener('keydown',e=>{const overlay=document.querySelector('.gmail-review-overlay');if(!overlay||e.defaultPrevented)return;if(e.key==='Escape'){e.preventDefault();closeGmailDialog();}else if(e.key==='Tab'){const controls=[...overlay.querySelectorAll('button,input:not([type=hidden])')].filter(el=>!el.disabled&&el.getClientRects().length),first=controls[0],last=controls[controls.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});

const gmailInitialCandidates=JSON.parse(JSON.stringify(gmailCandidates));
function resetAuthenticatedGmail(){beginAuthenticatedGmailScan();gmailReview.email='alex@example.com';gmailReview.selected=new Set(['new-notion-team','new-figma-trial']);gmailReview.imported.clear();gmailReview.saving=false;gmailReview.dateOverride=false;gmailCandidates.splice(0,gmailCandidates.length,...JSON.parse(JSON.stringify(gmailInitialCandidates)));}

function gmailPrepareImport(selected,existingRecords,email,overrideDate,connectorId){const records=selected.map(c=>gmailApplyCandidate(c,existingRecords.find(r=>r.id===c.targetId),email,overrideDate,connectorId));return records.every(Boolean)?records:null;}
